<?php
declare(strict_types=1);
header('Content-Type: application/json; charset=utf-8');header('X-Content-Type-Options: nosniff');header('Cache-Control: no-store, max-age=0');header('Referrer-Policy: same-origin');header('X-Frame-Options: DENY');
function reply(int $s,array $b): never{http_response_code($s);echo json_encode($b,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function method(string ...$m):void{if(!in_array($_SERVER['REQUEST_METHOD']??'GET',$m,true)){header('Allow: '.implode(', ',$m));reply(405,['ok'=>false,'message'=>'Method not allowed.']);}}
function body():array{$raw=file_get_contents('php://input');if(strlen($raw)>65536)reply(413,['ok'=>false,'message'=>'Request too large.']);$d=json_decode($raw?:'{}',true);if(!is_array($d))reply(400,['ok'=>false,'message'=>'Invalid JSON.']);return $d;}
function clean($v,int $n=500):string{if(!is_string($v)&&!is_numeric($v))return '';return mb_substr(trim(preg_replace('/[\x00-\x1F\x7F]/u','',(string)$v)??''),0,$n,'UTF-8');}
function phone($v):string{return preg_replace('/[^0-9+]/','',clean($v,30))??'';}
function db():PDO{static $p=null;if($p instanceof PDO)return $p;$f=__DIR__.'/config.local.php';if(!is_file($f))reply(503,['ok'=>false,'message'=>'Website database is not configured yet.']);$c=require $f;foreach(['host','name','user','password'] as $k)if(!isset($c[$k]))reply(503,['ok'=>false,'message'=>'Database configuration incomplete.']);try{$p=new PDO('mysql:host='.$c['host'].';dbname='.$c['name'].';charset=utf8mb4',$c['user'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);}catch(Throwable $e){error_log('LBFP DB error: '.$e->getMessage());reply(503,['ok'=>false,'message'=>'Database temporarily unavailable.']);}return $p;}
function same_origin():void{$o=$_SERVER['HTTP_ORIGIN']??'';if($o==='')return;$h=strtolower(explode(':',$_SERVER['HTTP_HOST']??'')[0]);$p=parse_url($o);if(!$p||strtolower((string)($p['host']??''))!==$h)reply(403,['ok'=>false,'message'=>'Cross-origin request denied.']);}
function limit(string $scope,int $max=12,int $seconds=600):void{$p=db();$key=hash('sha256',$scope.'|'.($_SERVER['REMOTE_ADDR']??'unknown'));try{$p->exec('DELETE FROM api_rate_limits WHERE window_start < (UTC_TIMESTAMP() - INTERVAL 1 DAY)');$q=$p->prepare('SELECT request_count,window_start FROM api_rate_limits WHERE rate_key=?');$q->execute([$key]);$r=$q->fetch();if(!$r){$p->prepare('INSERT INTO api_rate_limits(rate_key,request_count,window_start) VALUES(?,1,UTC_TIMESTAMP())')->execute([$key]);return;}if(strtotime($r['window_start'])<time()-$seconds){$p->prepare('UPDATE api_rate_limits SET request_count=1,window_start=UTC_TIMESTAMP() WHERE rate_key=?')->execute([$key]);return;}if((int)$r['request_count'] >= $max)reply(429,['ok'=>false,'message'=>'Too many requests. Wait a few minutes and try again.']);$p->prepare('UPDATE api_rate_limits SET request_count=request_count+1 WHERE rate_key=?')->execute([$key]);}catch(PDOException $e){error_log('LBFP rate limit error: '.$e->getMessage());reply(503,['ok'=>false,'message'=>'Service temporarily unavailable.']);}}
function upsert_customer(PDO $p,string $ph,array $d):int{$email=filter_var(clean($d['email']??'',190),FILTER_VALIDATE_EMAIL)?:null;$name=clean($d['name']??'',100);$addr=clean($d['address']??'',500);$q=$p->prepare('SELECT id FROM customers WHERE phone=? LIMIT 1');$q->execute([$ph]);$id=$q->fetchColumn();if($id){$p->prepare("UPDATE customers SET name=?,email=COALESCE(?,email),default_address=IF(?<>'',?,default_address),updated_at=UTC_TIMESTAMP() WHERE id=?")->execute([$name,$email,$addr,$addr,(int)$id]);return (int)$id;}$p->prepare('INSERT INTO customers(name,phone,email,default_address,created_at,updated_at) VALUES(?,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute([$name,$ph,$email,$addr]);return (int)$p->lastInsertId();}
